-- TPC-DS Test_Query Query 481
-- Based on: query63.tpl (medium)
-- Variation: 10

 select  * from (select i_manager_id ,sum(ss_sales_price) sum_sales ,avg(sum(ss_sales_price)) over (partition by i_manager_id) avg_monthly_sales from item ,store_sales ,date_dim ,store where ss_item_sk = i_item_sk and ss_sold_date_sk = d_date_sk and ss_store_sk = s_store_sk and d_month_seq in (6,16+3,15+1,25+4,40+5,32+3,32+8,47+8,47+9,98+9,38+10,81+12) and ((    i_category in ('Books','Children','Electronics') and i_class in ('personal','portable','reference','self-help') and i_brand in ('scholaramalgamalg #13','scholaramalgamalg #8', 'exportiunivamalg #7','scholaramalgamalg #9')) or(    i_category in ('Women','Music','Men') and i_class in ('accessories','classical','fragrances','pants') and i_brand in ('amalgimporto #2','edu packscholar #2','exportiimporto #1', 'importoamalg #2'))) group by i_manager_id, d_moy) tmp1 where case when avg_monthly_sales > 1 then abs (sum_sales - avg_monthly_sales) / avg_monthly_sales else null end > 0.3 order by i_manager_id ,avg_monthly_sales ,sum_sales limit 99;
